interface Item {
  id: string;
  name: string;
}

const UNIQUE = (() => {
  let n = 0;
  return () => `repo-spec-${++n}`;
})();

function buildProvider(overrides: Partial<RepositoryProvider<Item, any>> = {}): RepositoryProvider<Item, any> {
  return {
    list: jasmine
      .createSpy('list')
      .and.callFake(() => of({ hasNext: false, next: null, content: [{ id: '1', name: 'One' }] } as Slide<Item>)),
    retrieve: jasmine.createSpy('retrieve').and.returnValue(of({ id: '1', name: 'Remote' })),
    add: jasmine.createSpy('add').and.callFake((item: Item) => of(item)),
    update: jasmine.createSpy('update').and.callFake((_key: string, item: Item) => of(item)),
    patch: jasmine.createSpy('patch').and.callFake((_key: string, item: Item) => of(item)),
    delete: jasmine.createSpy('delete').and.returnValue(of(undefined)),
    downloadFile: jasmine.createSpy('downloadFile').and.returnValue(of(new DownloadBlob(new Blob(), 'file.txt'))),
    storeFile: jasmine.createSpy('storeFile').and.returnValue(of(new UploadProgress(50, 100))),
    ...overrides,
  } as unknown as RepositoryProvider<Item, any>;
}

function buildRepo(
  provider: RepositoryProvider<Item, any>,
  name = UNIQUE(),
  extra: Partial<RepositoryMetadata<Item, any>> = {},
) {
  return new RepositoryService<Item, any>({ key: 'id', name, provider, ...extra }, TestBed.inject(RepositoryStore));
}

/** Ejecuta los effects y espera a que los recursos terminen de cargar. */
async function settle() {
  TestBed.tick();
  await TestBed.inject(ApplicationRef).whenStable();
}

/** Ejecuta los effects y deja pasar las microtareas, sin esperar a recursos que no terminan. */
async function flush() {
  TestBed.tick();
  await new Promise((resolve) => setTimeout(resolve));
}

