  // ── projections keep dates and resolve references (DATA-10) ───────────────

  describe('projection copies', () => {
    interface Dated {
      id: string;
      registeredAt: Date | string;
      tenant?: { $ref: string } | null;
    }

    function datedRepo(content: Dated[], tenantName = 'Main') {
      const tenantProvider = buildProvider({
        retrieve: jasmine.createSpy('retrieve').and.callFake((id: string) => of({ id, name: tenantName })),
      });
      const provider = buildProvider({
        list: jasmine.createSpy('list').and.returnValue(of({ hasNext: false, next: null, content })),
        retrieve: jasmine.createSpy('retrieve').and.returnValue(of(content[0])),
      });
      const tenantMeta = { key: 'id', name: UNIQUE(), provider: tenantProvider };
      const repo = buildRepo(provider as any, UNIQUE(), {
        entity: { id: 'id', datetimes: ['registeredAt'] },
        reference: (name) => (name === 'tenant' ? tenantMeta : null),
      });
      return { repo, tenantProvider };
    }

    it('keeps Date fields as Date in projections() rows', async () => {
      const { repo } = datedRepo([{ id: '1', registeredAt: '2025-10-30T10:00:00Z', tenant: { $ref: 't1' } }]);
      const shift = TestBed.runInInjectionContext(() => repo.projections(['tenant']));
      shift.fetch({});
      await settle();
      const row = shift()![0];
      expect(row.registeredAt instanceof Date).toBeTrue();
      expect(row.registeredAt.toISOString()).toBe('2025-10-30T10:00:00.000Z');
    });

    it('exposes each reference as a signal with the referenced item', async () => {
      const { repo, tenantProvider } = datedRepo([
        { id: '1', registeredAt: '2025-10-30T10:00:00Z', tenant: { $ref: 't1' } },
        { id: '2', registeredAt: '2025-10-30T10:00:00Z', tenant: { $ref: 't1' } },
        { id: '3', registeredAt: '2025-10-30T10:00:00Z', tenant: null },
      ]);
      const shift = TestBed.runInInjectionContext(() => repo.projections(['tenant']));
      shift.fetch({});
      await settle();
      const rows = shift()!;
      expect(rows[0].tenant()).toEqual({ id: 't1', name: 'Main' });
      expect(rows[1].tenant).toBe(rows[0].tenant);
      expect(rows[2].tenant()).toBeUndefined();
      expect(tenantProvider.retrieve).toHaveBeenCalledTimes(1);
    });

    it('keeps Date fields as Date in projection()', async () => {
      const { repo } = datedRepo([{ id: '1', registeredAt: '2025-10-30T10:00:00Z', tenant: { $ref: 't1' } }]);
      const tick = TestBed.runInInjectionContext(() => repo.projection(['tenant']));
      tick.fetch('1');
      await settle();
      expect(tick().registeredAt instanceof Date).toBeTrue();
      expect(tick().tenant()?.name).toBe('Main');
    });
  });

